import { booleanAttribute, Directive, HostListener, inject, input } from '@angular/core';
import { addClass, findSingle, removeClass } from '@primeuix/utils';
import { BaseComponent } from 'primeng/basecomponent';
import { TREETABLE_INSTANCE } from './treetable-service';
import type { TreeTable } from './treetable';

@Directive({
    selector: '[ttEditableColumn]',
    standalone: true
})
export class TTEditableColumn extends BaseComponent {
    data = input<any>(undefined, { alias: 'ttEditableColumn' });

    field = input<any>(undefined, { alias: 'ttEditableColumnField' });

    ttEditableColumnDisabled = input(undefined, { transform: booleanAttribute });

    tt = inject<TreeTable>(TREETABLE_INSTANCE);

    onAfterViewInit() {
        if (this.isEnabled()) {
            !this.$unstyled() && addClass(this.el.nativeElement, 'p-editable-column');
            this.el?.nativeElement.setAttribute('data-p-editable-column', 'true');
        }
    }

    @HostListener('click', ['$event'])
    onClick(event: MouseEvent) {
        if (this.isEnabled()) {
            this.requestEdit();
        }
    }

    /**
     * Keyboard entry point: the cell editor host is in the tab order and opens
     * its editor on focus, so Tab lands on the cell and starts editing without
     * a mouse. `editingCellClick` is normally consumed by the document click
     * that follows a mouse open — a keyboard open has no such click, so it is
     * reset on the next tick to keep the first outside click closing the cell.
     */
    openCellFromFocus() {
        if (!this.isEnabled()) {
            return;
        }

        this.requestEdit();
        setTimeout(() => (this.tt.editingCellClick = false));
    }

    private requestEdit() {
        this.tt.editingCellClick = true;

        if (this.tt.editingCell) {
            if (this.tt.editingCell !== this.el.nativeElement) {
                if (!this.tt.isEditingCellValid()) {
                    return;
                }

                if (this.tt.editingCell) {
                    !this.$unstyled() && removeClass(this.tt.editingCell, 'p-cell-editing');
                    // The cell being left keeps its editing marker otherwise — only
                    // Enter/Escape closes reset it, not switching to another cell.
                    this.tt.editingCell.setAttribute('data-p-cell-editing', 'false');
                }
                this.openCell();
            }
        } else {
            this.openCell();
        }
    }

    openCell() {
        this.tt.updateEditingCell(this.el.nativeElement, this.data(), this.field());
        !this.$unstyled() && addClass(this.el.nativeElement, 'p-cell-editing');
        this.el?.nativeElement.setAttribute('data-p-cell-editing', 'true');
        this.tt.onEditInit.emit({ field: this.field(), data: this.data() });
        this.tt.editingCellClick = true;
        setTimeout(() => {
            let focusable = <any>findSingle(this.el.nativeElement, 'input, textarea');
            if (focusable) {
                focusable.focus();
            }
        }, 50);
    }

    closeEditingCell() {
        if (this.tt.editingCell) !this.$unstyled() && removeClass(this.tt.editingCell, 'p-cell-editing');
        this.tt.editingCell = null;
        this.tt.unbindDocumentEditListener();
    }

    /**
     * Keyboard closes (Enter/Escape) must hand focus back somewhere — the editor
     * input unmounts, and without this the focus falls to <body>. The cell
     * editor host is a tab stop, so focus returns to it (Tab then continues to
     * the next focusable from the same position). The suppress flag keeps that
     * programmatic focus from immediately reopening the editor it just closed.
     */
    private suppressFocusOpen = false;

    consumeSuppressedFocusOpen(): boolean {
        const suppressed = this.suppressFocusOpen;
        this.suppressFocusOpen = false;
        return suppressed;
    }

    private focusEditorHost() {
        const host = findSingle(this.el?.nativeElement, 'p-treetable-cell-editor, p-treetablecelleditor') as HTMLElement | null;
        if (host) {
            this.suppressFocusOpen = true;
            host.focus();
        }
    }

    @HostListener('keydown', ['$event'])
    onKeyDown(event: KeyboardEvent) {
        // Only intercept keys while THIS cell's editor is open. Otherwise Enter/
        // Space must reach the cell's interactive children natively (e.g. the
        // row toggler button) and Tab must follow the normal tab order.
        const editing = !!this.tt.editingCell && event.target instanceof Node && this.tt.editingCell.contains(event.target);
        if (!editing) {
            return;
        }

        if (this.isEnabled()) {
            //enter
            if (event.keyCode == 13 && !event.shiftKey) {
                if (this.tt.isEditingCellValid()) {
                    if (this.tt.editingCell) {
                        !this.$unstyled() && removeClass(this.tt.editingCell, 'p-cell-editing');
                        this.el?.nativeElement.setAttribute('data-p-cell-editing', 'false');
                    }
                    this.closeEditingCell();
                    this.tt.onEditComplete.emit({ field: this.field(), data: this.data() });
                    this.focusEditorHost();
                }

                event.preventDefault();
            }

            //escape
            else if (event.keyCode == 27) {
                if (this.tt.isEditingCellValid()) {
                    if (this.tt.editingCell) {
                        !this.$unstyled() && removeClass(this.tt.editingCell, 'p-cell-editing');
                        this.el?.nativeElement.setAttribute('data-p-cell-editing', 'false');
                    }
                    this.closeEditingCell();
                    this.tt.onEditCancel.emit({ field: this.field(), data: this.data() });
                    this.focusEditorHost();
                }

                event.preventDefault();
            }

            // Tab is intentionally left to the browser: editable cells are real
            // tab stops (see TreeTableCellEditor.hostTabindex), so sequential
            // focus naturally reaches whatever comes next in DOM order — the
            // next cell, a row toggler between rows, or an element outside the
            // table. The focusout handler below commits the edit on the way out.
        }
    }

    /**
     * Closes the editor when focus leaves the cell (native Tab/Shift+Tab or a
     * programmatic focus move). The edit is committed — with template-driven
     * bindings the value is already applied, closing only swaps the input back
     * to output. Focus changes within the cell (input ↔ toggler ↔ host) and
     * non-focus targets (relatedTarget null, e.g. window blur) are ignored.
     */
    @HostListener('focusout', ['$event'])
    onFocusOut(event: FocusEvent) {
        const cell = this.el?.nativeElement;
        const editingThisCell = this.tt.editingCell === cell;
        const target = event.relatedTarget;

        if (!editingThisCell || !(target instanceof Node) || cell.contains(target)) {
            return;
        }

        if (this.tt.isEditingCellValid()) {
            !this.$unstyled() && removeClass(cell, 'p-cell-editing');
            cell.setAttribute('data-p-cell-editing', 'false');
            this.closeEditingCell();
            this.tt.onEditComplete.emit({ field: this.field(), data: this.data() });
        }
    }

    isEnabled() {
        return this.ttEditableColumnDisabled() !== true;
    }
}
