import { Directive, HostListener, inject, input } from '@angular/core';
import { find, findSingle, getIndex } from '@primeuix/utils';
import { BaseComponent } from 'primeng/basecomponent';
import { Bind } from 'primeng/bind';
import { TreeTableStyle } from './style/treetablestyle';
import { TREETABLE_INSTANCE } from './treetable-service';
import type { TreeTable } from './treetable';

@Directive({
    selector: '[ttRow]',
    standalone: true,
    host: {
        '[class]': 'hostClass',
        '[attr.aria-expanded]': 'expanded',
        '[attr.aria-level]': 'level',
        role: 'row'
    },
    providers: [TreeTableStyle],
    hostDirectives: [Bind]
})
export class TTRow extends BaseComponent {
    hostName = 'TreeTable';

    bindDirectiveInstance = inject(Bind, { self: true });

    tt = inject<TreeTable>(TREETABLE_INSTANCE);

    onAfterViewChecked(): void {
        this.bindDirectiveInstance.setAttrs(this.ptm('row', this.ptmOptions()));
    }

    get level() {
        return this.rowNode()?.['level'] + 1;
    }

    get hostClass() {
        return this.cn('p-element', this.rowNode()?.node['styleClass']);
    }

    get expanded() {
        return this.rowNode()?.node['expanded'];
    }

    rowNode = input<any>(undefined, { alias: 'ttRow' });

    _componentStyle = inject(TreeTableStyle);

    @HostListener('keydown', ['$event'])
    onKeyDown(event: KeyboardEvent) {
        // Skip row/cell keyboard navigation while a cell editor is open so that keys such as
        // ArrowLeft/ArrowRight move the caret inside the editor input instead of moving focus
        // out of the open editor and discarding the in-progress edit.
        if (this.isEditingCellTarget(event.target)) {
            return;
        }

        switch (event.code) {
            case 'ArrowDown':
                this.onArrowDownKey(event);
                break;

            case 'ArrowUp':
                this.onArrowUpKey(event);
                break;

            case 'ArrowRight':
                this.onArrowRightKey(event);
                break;

            case 'ArrowLeft':
                this.onArrowLeftKey(event);
                break;

            case 'Home':
                this.onHomeKey(event);
                break;

            case 'End':
                this.onEndKey(event);
                break;

            default:
                break;
        }
    }

    private isEditingCellTarget(target: EventTarget | null): boolean {
        const editingCell = this.tt?.editingCell;
        return !!(editingCell && target instanceof Node && editingCell.contains(target));
    }

    onArrowDownKey(event: KeyboardEvent) {
        this.focusSiblingToggler('next');
        event.preventDefault();
    }

    onArrowUpKey(event: KeyboardEvent) {
        this.focusSiblingToggler('previous');
        event.preventDefault();
    }

    onArrowRightKey(event: KeyboardEvent) {
        if (this.togglerButton(this.el?.nativeElement) && !this.expanded && this.rowNode()?.node['children']) {
            this.expand(event);
        }
        event.preventDefault();
    }

    onArrowLeftKey(event: KeyboardEvent) {
        if (this.expanded) {
            this.tt.toggleRowIndex = getIndex(this.el.nativeElement);
            this.collapse(event);
            this.restoreFocus();
        }
        event.preventDefault();
    }

    onHomeKey(event: KeyboardEvent) {
        const rows = <any>find(this.tt.el?.nativeElement, `tr[aria-level="${this.level}"]`);
        for (const row of rows) {
            const toggler = this.togglerButton(row);
            if (toggler) {
                toggler.focus();
                break;
            }
        }
        event.preventDefault();
    }

    onEndKey(event: KeyboardEvent) {
        const rows = <any>find(this.tt.el?.nativeElement, `tr[aria-level="${this.level}"]`);
        for (let i = rows.length - 1; i >= 0; i--) {
            const toggler = this.togglerButton(rows[i]);
            if (toggler) {
                toggler.focus();
                break;
            }
        }
        event.preventDefault();
    }

    expand(event: Event) {
        this.tt.toggleRowIndex = getIndex(this.el.nativeElement);
        this.rowNode().node['expanded'] = true;

        this.tt.updateSerializedValue();
        this.tt.tableService.onUIUpdate(this.tt.value);
        this.restoreFocus();

        this.tt.onNodeExpand.emit({
            originalEvent: event,
            node: this.rowNode().node
        });
    }

    collapse(event: Event) {
        this.rowNode().node['expanded'] = false;

        this.tt.updateSerializedValue();
        this.tt.tableService.onUIUpdate(this.tt.value);

        this.tt.onNodeCollapse.emit({ originalEvent: event, node: this.rowNode().node });
    }

    /**
     * Focus model: rows are not focusable — the row's toggler button carries
     * keyboard focus (Tab reaches it, Enter/Space toggles, arrows move between
     * visible togglers). Rows never show a focus outline.
     */
    private togglerButton(row: Element | null | undefined): HTMLElement | null {
        if (!row) return null;
        const button = findSingle(row, '[data-pc-section="rowtogglebutton"]') as HTMLElement | null;
        return button && button.style.visibility !== 'hidden' ? button : null;
    }

    private focusSiblingToggler(direction: 'next' | 'previous') {
        let sibling = direction === 'next' ? this.el?.nativeElement?.nextElementSibling : this.el?.nativeElement?.previousElementSibling;
        while (sibling) {
            const toggler = this.togglerButton(sibling);
            if (toggler) {
                toggler.focus();
                return;
            }
            sibling = direction === 'next' ? sibling.nextElementSibling : sibling.previousElementSibling;
        }
    }

    /** Re-focus the toggled row's toggler after the tbody re-renders. */
    restoreFocus() {
        setTimeout(() => {
            const tbody = findSingle(this.tt.el?.nativeElement, '[data-pc-section="tbody"]');
            const row = tbody?.children?.[this.tt.toggleRowIndex || 0] as Element | undefined;
            const toggler = this.togglerButton(row);
            toggler?.focus();
        }, 25);
    }

    ptmOptions() {
        return {
            context: {
                selectable: this.tt?.rowHover() || !!this.tt.selectionMode(),
                selected: this.tt.isSelected((<any>this.rowNode())?.node),
                scrollable: this.tt?.scrollable(),
                rowNode: this.rowNode()
            }
        };
    }
}
