import { NgTemplateOutlet } from '@angular/common';
import { Component, contentChild, inject, TemplateRef, ViewEncapsulation } from '@angular/core';
import { BaseComponent } from 'primeng/basecomponent';
import { Bind } from 'primeng/bind';
import { TREETABLE_INSTANCE } from './treetable-service';
import { TTEditableColumn } from './editable-column';
import type { TreeTable } from './treetable';

@Component({
    selector: 'p-treetablecelleditor, p-treetable-cell-editor',
    standalone: true,
    imports: [NgTemplateOutlet],
    template: `
        @if (editing) {
            <ng-container *ngTemplateOutlet="inputTemplate()"></ng-container>
        } @else {
            <ng-container *ngTemplateOutlet="outputTemplate()"></ng-container>
        }
    `,
    encapsulation: ViewEncapsulation.None,
    host: {
        '[attr.tabindex]': 'hostTabindex',
        '(focus)': 'onHostFocus()'
    },
    hostDirectives: [Bind]
})
export class TreeTableCellEditor extends BaseComponent {
    hostName = 'TreeTable';

    bindDirectiveInstance = inject(Bind, { self: true });

    onAfterViewChecked(): void {
        this.bindDirectiveInstance.setAttrs(this.ptm('cellEditor'));
    }

    /**
     * Closed editors render plain output text, which is not focusable — without
     * a tabindex the browser's sequential focus (Tab) would skip editable cells
     * entirely. The host joins the tab order so Tab reaches the cell, and focus
     * opens the editor (which then moves focus into the input).
     */
    get hostTabindex() {
        return this.editableColumn.isEnabled() ? 0 : null;
    }

    onHostFocus() {
        if (this.editableColumn.consumeSuppressedFocusOpen() || this.editing || !this.editableColumn.isEnabled()) {
            return;
        }

        this.editableColumn.openCellFromFocus();
    }

    inputTemplate = contentChild<TemplateRef<any>>('input', { descendants: false });

    outputTemplate = contentChild<TemplateRef<any>>('output', { descendants: false });

    tt = inject<TreeTable>(TREETABLE_INSTANCE);

    editableColumn = inject(TTEditableColumn);

    get editing() {
        return this.tt.editingCell === this.editableColumn.el.nativeElement;
    }
}
